function capacityMbps(bandwidthHz, snrDb) {
  // 1) convert dB to a linear ratio
  const snrLinear = Math.pow(10, snrDb / 10);
  // 2) Shannon: C = B * log2(1 + S/N)
  const bitsPerSec = bandwidthHz * Math.log2(1 + snrLinear);
  return Math.round(bitsPerSec / 1e6);
}

// 80 MHz channel, SNR = 30 dB
console.log(capacityMbps(80e6, 30) + ' Mbps');
